-- Library drafts (owner-approved load as editor-only drafts; not reviewed, not published).
insert into public.vv_library_versions (kind, taxon_id, version, content, sources, status, author_id)
 select $q$species$q$, id, 1, $q${"summary":"An invasive, day-biting mosquito that breeds in small containers of water. Established across much of southern and central Europe and detected in the UK on several occasions, usually near ports, motorway services and freight routes. A priority species for surveillance.","identification":["Black body with bright white scales","A single white stripe running down the middle of the thorax (top of the body behind the head)","White bands on the legs","Small: around 2 to 10 mm"],"breeding_habitats":["Small water-holding containers: tyres, plant-pot saucers, buckets, water butts, blocked gutters, tarpaulins","Tree holes and other natural containers","Eggs are laid just above the waterline and survive drying out for months"],"activity":"Bites mainly during the day, with peaks in the early morning and late afternoon; aggressive and persistent biter, often outdoors.","season":"In Europe mainly active from late spring to autumn; eggs can overwinter.","uk_status":"Not established in the UK. Detections are reported to and coordinated with UKHSA. Treat any finding as a possible incursion.","diseases":["Can transmit dengue, chikungunya and Zika viruses (local transmission has occurred in Europe)"],"best_traps":["ovitrap","bg_sentinel"],"lures":["BG-Lure or similar human-skin odour lure with BG-Sentinel; CO2 increases catches"],"images":[{"url":"https://thumb.wikimedia.org/wikipedia/commons/thumb/7/73/CDC-Gathany-Aedes-albopictus-2.jpg/960px-CDC-Gathany-Aedes-albopictus-2.jpg","credit":"James Gathany, CDC","licence":"Public domain","source_url":"https://commons.wikimedia.org/wiki/File:CDC-Gathany-Aedes-albopictus-2.jpg","caption":"Female Aedes albopictus"}]}$q$::jsonb, $q$[{"title":"ECDC: Aedes albopictus factsheet","url":"https://www.ecdc.europa.eu/en/disease-vectors/facts/mosquito-factsheets/aedes-albopictus"},{"title":"ECDC: Guidelines for the surveillance of invasive mosquitoes in Europe","url":"https://www.ecdc.europa.eu/en/publications-data/guidelines-surveillance-invasive-mosquitoes-europe"},{"title":"GOV.UK: Mosquito surveillance","url":"https://www.gov.uk/government/publications/mosquito-surveillance"}]$q$::jsonb, 'draft', null from public.vv_taxa where key = $q$aedes_albopictus$q$
 and not exists (select 1 from public.vv_library_versions v join public.vv_taxa t on t.id = v.taxon_id where t.key = $q$aedes_albopictus$q$);
insert into public.vv_library_versions (kind, taxon_id, version, content, sources, status, author_id)
 select $q$species$q$, id, 1, $q${"summary":"An invasive, container-breeding mosquito of tropical and subtropical regions, closely associated with people and buildings. Not established in the UK; occasional introductions are possible through ports and airports.","identification":["Dark body with white scales","A lyre-shaped pattern of white scales on the thorax","White bands on the legs"],"breeding_habitats":["Artificial containers in and around buildings: water storage, flower vases, tyres, discarded containers"],"activity":"Bites during the day, often indoors or close to houses.","season":"Needs warm conditions; unlikely to survive UK winters outdoors.","uk_status":"Not established in the UK. Any detection is significant and should be reported to UKHSA.","diseases":["The main vector of dengue, yellow fever, chikungunya and Zika viruses worldwide"],"best_traps":["ovitrap","bg_sentinel"],"lures":["BG-Lure with BG-Sentinel"],"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/8/83/Aedes_aegypti_during_blood_meal.jpg","credit":"James Gathany","licence":"Public domain","source_url":"https://commons.wikimedia.org/wiki/File:Aedes_aegypti_during_blood_meal.jpg","caption":"Female Aedes aegypti feeding"}]}$q$::jsonb, $q$[{"title":"ECDC: Aedes aegypti factsheet","url":"https://www.ecdc.europa.eu/en/disease-vectors/facts/mosquito-factsheets/aedes-aegypti"},{"title":"ECDC: Guidelines for the surveillance of invasive mosquitoes in Europe","url":"https://www.ecdc.europa.eu/en/publications-data/guidelines-surveillance-invasive-mosquitoes-europe"},{"title":"GOV.UK: Mosquito surveillance","url":"https://www.gov.uk/government/publications/mosquito-surveillance"}]$q$::jsonb, 'draft', null from public.vv_taxa where key = $q$aedes_aegypti$q$
 and not exists (select 1 from public.vv_library_versions v join public.vv_taxa t on t.id = v.taxon_id where t.key = $q$aedes_aegypti$q$);
insert into public.vv_library_versions (kind, taxon_id, version, content, sources, status, author_id)
 select $q$species$q$, id, 1, $q${"summary":"An invasive container-breeding mosquito, established in parts of central and western Europe. Tolerates cooler climates than Aedes albopictus.","identification":["Dark body with golden-yellow stripes (lines) on the thorax","White bands on the legs"],"breeding_habitats":["Rock pools, tree holes and artificial containers such as tyres, water butts and cemetery vases"],"activity":"Bites mainly during the day.","season":"Active from spring to autumn; tolerates cool temperatures.","uk_status":"Detections have been reported in the UK; check the current position with UKHSA.","diseases":["A potential vector of several viruses in laboratory studies; its role in transmission in Europe is considered limited"],"best_traps":["ovitrap","bg_sentinel"],"images":[{"url":"https://thumb.wikimedia.org/wikipedia/commons/thumb/8/8b/CDC_7887_Ochlerotatus_japonicus.jpg/960px-CDC_7887_Ochlerotatus_japonicus.jpg","credit":"James Gathany, CDC","licence":"Public domain","source_url":"https://commons.wikimedia.org/wiki/File:CDC_7887_Ochlerotatus_japonicus.jpg","caption":"Aedes (Ochlerotatus) japonicus"}]}$q$::jsonb, $q$[{"title":"ECDC: Aedes japonicus factsheet","url":"https://www.ecdc.europa.eu/en/disease-vectors/facts/mosquito-factsheets/aedes-japonicus"},{"title":"ECDC: Guidelines for the surveillance of invasive mosquitoes in Europe","url":"https://www.ecdc.europa.eu/en/publications-data/guidelines-surveillance-invasive-mosquitoes-europe"}]$q$::jsonb, 'draft', null from public.vv_taxa where key = $q$aedes_japonicus$q$
 and not exists (select 1 from public.vv_library_versions v join public.vv_taxa t on t.id = v.taxon_id where t.key = $q$aedes_japonicus$q$);
insert into public.vv_library_versions (kind, taxon_id, version, content, sources, status, author_id)
 select $q$species$q$, id, 1, $q${"summary":"A native coastal mosquito that breeds in brackish water in salt marshes. Can be a significant nuisance biter in coastal communities.","identification":["Brown mosquito with pale bands on the legs; identification to species normally needs a microscope and key"],"breeding_habitats":["Brackish water in coastal salt marshes and grazing marshes"],"activity":"Bites readily, including during the day near breeding sites.","season":"Can be active from early spring to late autumn.","uk_status":"Native and widespread in suitable coastal habitats.","diseases":["Mainly a nuisance species; considered a potential vector in some studies"],"best_traps":["cdc_light","bg_sentinel","larval_dip"],"images":[{"url":"https://thumb.wikimedia.org/wikipedia/commons/thumb/6/69/Aedes_detritus.jpg/960px-Aedes_detritus.jpg","credit":"The Trustees of the Natural History Museum, London","licence":"CC BY 4.0","source_url":"https://commons.wikimedia.org/wiki/File:Aedes_detritus.jpg","caption":"Aedes detritus (museum specimen)"}]}$q$::jsonb, $q$[{"title":"ECDC: Guidelines for the surveillance of native mosquitoes in Europe","url":"https://www.ecdc.europa.eu/en/publications-data/guidelines-surveillance-native-mosquitoes-europe"},{"title":"GOV.UK: Mosquito surveillance","url":"https://www.gov.uk/government/publications/mosquito-surveillance"}]$q$::jsonb, 'draft', null from public.vv_taxa where key = $q$aedes_detritus$q$
 and not exists (select 1 from public.vv_library_versions v join public.vv_taxa t on t.id = v.taxon_id where t.key = $q$aedes_detritus$q$);
insert into public.vv_library_versions (kind, taxon_id, version, content, sources, status, author_id)
 select $q$species$q$, id, 1, $q${"summary":"A native floodwater mosquito that can emerge in large numbers after flooding of river meadows and grassland.","identification":["Brown mosquito with narrow pale bands on the leg joints"],"breeding_habitats":["Temporary flood pools on river floodplains and wet grassland"],"activity":"Mainly bites at dusk and night; can disperse several kilometres.","season":"Summer, especially after flooding.","uk_status":"Native; found in parts of the UK.","diseases":["A potential vector of some viruses; mainly a nuisance species in the UK"],"best_traps":["cdc_light","mosquito_magnet"],"images":[{"url":"https://thumb.wikimedia.org/wikipedia/commons/thumb/7/7f/Aedes_vexans.jpg/960px-Aedes_vexans.jpg","credit":"CDC","licence":"Public domain","source_url":"https://commons.wikimedia.org/wiki/File:Aedes_vexans.jpg","caption":"Aedes vexans"}]}$q$::jsonb, $q$[{"title":"ECDC: Guidelines for the surveillance of native mosquitoes in Europe","url":"https://www.ecdc.europa.eu/en/publications-data/guidelines-surveillance-native-mosquitoes-europe"}]$q$::jsonb, 'draft', null from public.vv_taxa where key = $q$aedes_vexans$q$
 and not exists (select 1 from public.vv_library_versions v join public.vv_taxa t on t.id = v.taxon_id where t.key = $q$aedes_vexans$q$);
insert into public.vv_library_versions (kind, taxon_id, version, content, sources, status, author_id)
 select $q$species$q$, id, 1, $q${"summary":"A native tree-hole mosquito that has adapted to breed in artificial habitats such as tyres and water-filled containers rich in organic matter.","identification":["Dark grey-blue mosquito; rests with its body at an angle to the surface (typical of Anopheles)"],"breeding_habitats":["Water-filled tree holes","Tyres and containers with decaying leaves and organic matter"],"activity":"Bites people readily, often at dusk and during the day in shade.","season":"Late spring to autumn.","uk_status":"Native and widespread.","diseases":["Capable of transmitting malaria parasites in laboratory conditions; considered a low risk in the UK"],"best_traps":["bg_sentinel","ovitrap"],"images":[{"url":"https://thumb.wikimedia.org/wikipedia/commons/thumb/c/c3/Anopheles_plumbeus_75398458.jpg/960px-Anopheles_plumbeus_75398458.jpg","credit":"Peter Gabler","licence":"CC0","source_url":"https://commons.wikimedia.org/wiki/File:Anopheles_plumbeus_75398458.jpg","caption":"Anopheles plumbeus"}]}$q$::jsonb, $q$[{"title":"ECDC: Guidelines for the surveillance of native mosquitoes in Europe","url":"https://www.ecdc.europa.eu/en/publications-data/guidelines-surveillance-native-mosquitoes-europe"}]$q$::jsonb, 'draft', null from public.vv_taxa where key = $q$anopheles_plumbeus$q$
 and not exists (select 1 from public.vv_library_versions v join public.vv_taxa t on t.id = v.taxon_id where t.key = $q$anopheles_plumbeus$q$);
insert into public.vv_library_versions (kind, taxon_id, version, content, sources, status, author_id)
 select $q$species$q$, id, 1, $q${"summary":"A group of closely related Anopheles species (a species complex). Some members historically transmitted malaria in Europe, including the UK.","identification":["Dark spots on the wings","Rests at an angle to the surface","Species within the complex can only be told apart reliably by egg features or molecular methods"],"breeding_habitats":["Large, clean, still or slow-moving water with vegetation: ditches, ponds, marsh edges; some species tolerate brackish water"],"activity":"Mainly dusk and night; some members enter buildings and animal housing.","season":"Adults overwinter in sheltered places such as outbuildings.","uk_status":"Native members of the complex are present in the UK.","diseases":["Historical vectors of malaria in Europe"],"best_traps":["cdc_light","mosquito_magnet"],"images":[{"url":"https://thumb.wikimedia.org/wikipedia/commons/thumb/8/8a/Anopheles_maculipennis_01.JPG/960px-Anopheles_maculipennis_01.JPG","credit":"AfroBrazilian","licence":"CC BY-SA 4.0","source_url":"https://commons.wikimedia.org/wiki/File:Anopheles_maculipennis_01.JPG","caption":"Anopheles maculipennis (complex)"}]}$q$::jsonb, $q$[{"title":"ECDC: Guidelines for the surveillance of native mosquitoes in Europe","url":"https://www.ecdc.europa.eu/en/publications-data/guidelines-surveillance-native-mosquitoes-europe"}]$q$::jsonb, 'draft', null from public.vv_taxa where key = $q$anopheles_maculipennis_sl$q$
 and not exists (select 1 from public.vv_library_versions v join public.vv_taxa t on t.id = v.taxon_id where t.key = $q$anopheles_maculipennis_sl$q$);
insert into public.vv_library_versions (kind, taxon_id, version, content, sources, status, author_id)
 select $q$species$q$, id, 1, $q${"summary":"The common house mosquito: one of the most widespread mosquitoes in the UK, including in towns. Forms with different behaviour exist within the group.","identification":["Light brown mosquito with pale bands on the abdomen","No pattern of white scales on the legs"],"breeding_habitats":["Water butts, drains, ponds, ditches, blocked gutters and other standing water, often rich in organic matter"],"activity":"Mostly dusk and night; one form commonly bites people and enters buildings.","season":"Spring to autumn; females overwinter in buildings and cellars.","uk_status":"Native and widespread.","diseases":["The main vector of West Nile virus in Europe (not currently circulating in the UK); also Usutu virus, detected in UK birds"],"best_traps":["gravid","cdc_light","bg_sentinel"],"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/3/35/Culex_pipiens_2007-1.jpg","credit":"Alvesgaspar","licence":"CC BY-SA 3.0","source_url":"https://commons.wikimedia.org/wiki/File:Culex_pipiens_2007-1.jpg","caption":"Culex pipiens"}]}$q$::jsonb, $q$[{"title":"ECDC: Guidelines for the surveillance of native mosquitoes in Europe","url":"https://www.ecdc.europa.eu/en/publications-data/guidelines-surveillance-native-mosquitoes-europe"},{"title":"GOV.UK: Mosquito surveillance","url":"https://www.gov.uk/government/publications/mosquito-surveillance"}]$q$::jsonb, 'draft', null from public.vv_taxa where key = $q$culex_pipiens_sl$q$
 and not exists (select 1 from public.vv_library_versions v join public.vv_taxa t on t.id = v.taxon_id where t.key = $q$culex_pipiens_sl$q$);
insert into public.vv_library_versions (kind, taxon_id, version, content, sources, status, author_id)
 select $q$species$q$, id, 1, $q${"summary":"A wetland mosquito of reed beds and marshes, recorded in parts of south-east England.","identification":["Small brown Culex; identification needs a microscope and key"],"breeding_habitats":["Reed beds, ditches and marshland with emergent vegetation"],"activity":"Bites birds and people, mainly at dusk and night.","season":"Summer.","uk_status":"Present locally in parts of England.","diseases":["A potential bridge vector of West Nile virus between birds and people"],"best_traps":["cdc_light","mosquito_magnet"]}$q$::jsonb, $q$[{"title":"ECDC: Guidelines for the surveillance of native mosquitoes in Europe","url":"https://www.ecdc.europa.eu/en/publications-data/guidelines-surveillance-native-mosquitoes-europe"}]$q$::jsonb, 'draft', null from public.vv_taxa where key = $q$culex_modestus$q$
 and not exists (select 1 from public.vv_library_versions v join public.vv_taxa t on t.id = v.taxon_id where t.key = $q$culex_modestus$q$);
insert into public.vv_library_versions (kind, taxon_id, version, content, sources, status, author_id)
 select $q$species$q$, id, 1, $q${"summary":"A large, common mosquito often found around homes and gardens; frequently noticed because of its size.","identification":["Large mosquito with dark spots on the wings","Clear pale bands on the legs"],"breeding_habitats":["Water butts, ditches, ponds and other standing water, including polluted water"],"activity":"Mainly dusk and night; females often enter buildings in autumn.","season":"Adults can be seen in most months; females overwinter in buildings.","uk_status":"Native and widespread.","diseases":["Mainly a nuisance species in the UK"],"best_traps":["cdc_light","gravid"],"images":[{"url":"https://thumb.wikimedia.org/wikipedia/commons/thumb/3/34/Culiseta_annulata_female_lateral_Chorzow.jpg/960px-Culiseta_annulata_female_lateral_Chorzow.jpg","credit":"Adrian Tync","licence":"CC BY-SA 4.0","source_url":"https://commons.wikimedia.org/wiki/File:Culiseta_annulata_female_lateral_Chorzow.jpg","caption":"Female Culiseta annulata"}]}$q$::jsonb, $q$[{"title":"ECDC: Guidelines for the surveillance of native mosquitoes in Europe","url":"https://www.ecdc.europa.eu/en/publications-data/guidelines-surveillance-native-mosquitoes-europe"}]$q$::jsonb, 'draft', null from public.vv_taxa where key = $q$culiseta_annulata$q$
 and not exists (select 1 from public.vv_library_versions v join public.vv_taxa t on t.id = v.taxon_id where t.key = $q$culiseta_annulata$q$);
insert into public.vv_library_versions (kind, taxon_id, version, content, sources, status, author_id)
 select $q$species$q$, id, 1, $q${"summary":"Use this when a mosquito has not been, or cannot be, identified to species: for example damaged specimens, or before the laboratory has reported. Record it as pending or inconclusive rather than guessing.","identification":["Long thin legs, a long proboscis (mouthparts) and scales on the wing veins distinguish mosquitoes from other small flies"],"notes":"Send unidentified specimens for identification where they may be invasive species.","images":[{"url":"https://thumb.wikimedia.org/wikipedia/commons/thumb/d/dc/Mosquito_2007-2.jpg/960px-Mosquito_2007-2.jpg","credit":"Alvesgaspar","licence":"CC BY-SA 3.0","source_url":"https://commons.wikimedia.org/wiki/File:Mosquito_2007-2.jpg","caption":"An adult mosquito"}]}$q$::jsonb, $q$[{"title":"ECDC: Guidelines for the surveillance of native mosquitoes in Europe","url":"https://www.ecdc.europa.eu/en/publications-data/guidelines-surveillance-native-mosquitoes-europe"}]$q$::jsonb, 'draft', null from public.vv_taxa where key = $q$culicidae_unidentified$q$
 and not exists (select 1 from public.vv_library_versions v join public.vv_taxa t on t.id = v.taxon_id where t.key = $q$culicidae_unidentified$q$);
insert into public.vv_library_versions (kind, trap_type_id, version, content, sources, status, author_id)
 select $q$trap$q$, id, 1, $q${"summary":"A collapsible fabric trap that draws mosquitoes in with an upward airflow and a lure that mimics human skin odour. The standard adult trap for container-breeding Aedes.","how_it_works":"A fan pulls air into a central funnel; attracted mosquitoes are drawn into a catch bag. A skin-odour lure (and optionally CO2) increases catches.","targets":["aedes_albopictus","aedes_aegypti","aedes_japonicus","culex_pipiens_sl"],"life_stages":["adults"],"setup":["Place on the ground on a level surface","Fit the lure and, if used, the CO2 supply","Check the fan runs and the catch bag is secure"],"placement":["In shade, sheltered from wind and rain","Near likely resting or breeding sites (vegetation, containers)","Away from competing attractants such as lights"],"servicing":"Collect the catch bag at least every 24 to 72 hours, depending on the programme, and replace the lure as the manufacturer advises.","tips":["Record the exact run time: it is the collection effort","Label the catch bag with trap, site and date before removing it"],"common_mistakes":["Running out of power without noticing (record as not completed, not no catch)","Placing in full sun or exposed wind"]}$q$::jsonb, $q$[{"title":"ECDC: Guidelines for the surveillance of invasive mosquitoes in Europe","url":"https://www.ecdc.europa.eu/en/publications-data/guidelines-surveillance-invasive-mosquitoes-europe"},{"title":"ECDC: Guidelines for the surveillance of native mosquitoes in Europe","url":"https://www.ecdc.europa.eu/en/publications-data/guidelines-surveillance-native-mosquitoes-europe"}]$q$::jsonb, 'draft', null from public.vv_trap_types where key = $q$bg_sentinel$q$
 and not exists (select 1 from public.vv_library_versions v join public.vv_trap_types t on t.id = v.trap_type_id where t.key = $q$bg_sentinel$q$);
insert into public.vv_library_versions (kind, trap_type_id, version, content, sources, status, author_id)
 select $q$trap$q$, id, 1, $q${"summary":"A small dark container with water and a surface for egg-laying (a paddle or strip). Simple and cheap; the standard early-warning trap for container-breeding Aedes.","how_it_works":"Gravid females lay eggs on the paddle just above the waterline. Paddles are collected and eggs counted and identified.","targets":["aedes_albopictus","aedes_aegypti","aedes_japonicus","anopheles_plumbeus"],"life_stages":["eggs"],"setup":["Fill with water (some programmes add a hay infusion)","Fit a fresh paddle or strip","Label the trap"],"placement":["In shade, near vegetation","On or near the ground, sheltered","Near likely breeding habitat such as tyres or containers"],"servicing":"Replace paddles and water usually every 1 to 2 weeks; never leave longer than about 7 days in warm weather, so it can't become a breeding site.","tips":["Many traps across an area give a better picture than a few","Keep paddles dry and labelled for the laboratory"],"common_mistakes":["Leaving it unserviced so larvae hatch and adults emerge","Letting it dry out (no water: record as not completed)"],"images":[{"url":"https://thumb.wikimedia.org/wikipedia/commons/thumb/0/02/Ovitrap_U.S._Army_Public_Health_Command.jpg/960px-Ovitrap_U.S._Army_Public_Health_Command.jpg","credit":"Graham Snodgrass, U.S. Army Public Health Command","licence":"Public domain","source_url":"https://commons.wikimedia.org/wiki/File:Ovitrap_U.S._Army_Public_Health_Command.jpg","caption":"An ovitrap"}]}$q$::jsonb, $q$[{"title":"ECDC: Guidelines for the surveillance of invasive mosquitoes in Europe","url":"https://www.ecdc.europa.eu/en/publications-data/guidelines-surveillance-invasive-mosquitoes-europe"}]$q$::jsonb, 'draft', null from public.vv_trap_types where key = $q$ovitrap$q$
 and not exists (select 1 from public.vv_library_versions v join public.vv_trap_types t on t.id = v.trap_type_id where t.key = $q$ovitrap$q$);
insert into public.vv_library_versions (kind, trap_type_id, version, content, sources, status, author_id)
 select $q$trap$q$, id, 1, $q${"summary":"A portable battery trap with a small light and fan, often baited with CO2 (dry ice or gas). Widely used for night-active species.","how_it_works":"Light and CO2 attract host-seeking mosquitoes; a fan draws them into a collection net or container.","targets":["culex_pipiens_sl","culex_modestus","anopheles_maculipennis_sl","aedes_vexans","aedes_detritus","culiseta_annulata"],"life_stages":["adults"],"setup":["Hang about 1.5 m above the ground","Fit charged battery and CO2 source","Run overnight (dusk to dawn)"],"placement":["Sheltered spot near vegetation or wetland edges","Away from other lights"],"servicing":"Collect the catch each morning and keep it cool for identification.","tips":["CO2 greatly increases catches","Record start and end times for collection effort"],"common_mistakes":["Flat battery overnight (record as not completed)","Catch left in the sun, damaging specimens"],"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/c/c0/CDC-LightTrap_200.jpg","credit":"United States National Park Service","licence":"Public domain","source_url":"https://commons.wikimedia.org/wiki/File:CDC-LightTrap_200.jpg","caption":"A CDC light trap"}]}$q$::jsonb, $q$[{"title":"ECDC: Guidelines for the surveillance of native mosquitoes in Europe","url":"https://www.ecdc.europa.eu/en/publications-data/guidelines-surveillance-native-mosquitoes-europe"}]$q$::jsonb, 'draft', null from public.vv_trap_types where key = $q$cdc_light$q$
 and not exists (select 1 from public.vv_library_versions v join public.vv_trap_types t on t.id = v.trap_type_id where t.key = $q$cdc_light$q$);
insert into public.vv_library_versions (kind, trap_type_id, version, content, sources, status, author_id)
 select $q$trap$q$, id, 1, $q${"summary":"A trap that attracts egg-laying (gravid) females with a tray of organically enriched water. Good for Culex and for virus testing because caught females have usually already fed.","how_it_works":"Females approaching the water to lay eggs are drawn up by a fan into a collection chamber.","targets":["culex_pipiens_sl","culiseta_annulata"],"life_stages":["adults (egg-laying females)"],"setup":["Fill the tray with an infusion (e.g. hay or grass water) prepared in advance","Fit the fan unit and collection chamber"],"placement":["On the ground in shade, near drains, gardens or standing water"],"servicing":"Collect daily; replace the infusion regularly.","tips":["Keep infusion recipe and age consistent so results are comparable"],"common_mistakes":["Infusion too fresh or too old, reducing catches"],"images":[{"url":"https://thumb.wikimedia.org/wikipedia/commons/thumb/8/88/CDC_Gravid_Trap_for_Mosquito_Surveillance_and_Captured_Culex_Mosquito.jpg/960px-CDC_Gravid_Trap_for_Mosquito_Surveillance_and_Captured_Culex_Mosquito.jpg","credit":"NIAID","licence":"CC BY 2.0","source_url":"https://commons.wikimedia.org/wiki/File:CDC_Gravid_Trap_for_Mosquito_Surveillance_and_Captured_Culex_Mosquito.jpg","caption":"A gravid trap"}]}$q$::jsonb, $q$[{"title":"ECDC: Guidelines for the surveillance of native mosquitoes in Europe","url":"https://www.ecdc.europa.eu/en/publications-data/guidelines-surveillance-native-mosquitoes-europe"}]$q$::jsonb, 'draft', null from public.vv_trap_types where key = $q$gravid$q$
 and not exists (select 1 from public.vv_library_versions v join public.vv_trap_types t on t.id = v.trap_type_id where t.key = $q$gravid$q$);
insert into public.vv_library_versions (kind, trap_type_id, version, content, sources, status, author_id)
 select $q$trap$q$, id, 1, $q${"summary":"A commercial trap that produces CO2 and warmth (often from propane) to attract biting mosquitoes. Sometimes used for longer-term catches.","how_it_works":"CO2, heat and moisture (and optionally a lure) attract mosquitoes, which are drawn into a net by a fan.","targets":["aedes_vexans","anopheles_maculipennis_sl","culex_modestus"],"life_stages":["adults"],"setup":["Follow the manufacturer's instructions for the gas supply and lure"],"placement":["Upwind of breeding areas, in shade, away from people"],"servicing":"Empty the net regularly; check the gas supply.","tips":["Note the gas and lure used: they affect what is caught"],"common_mistakes":["Running out of gas without noticing"]}$q$::jsonb, $q$[{"title":"ECDC: Guidelines for the surveillance of native mosquitoes in Europe","url":"https://www.ecdc.europa.eu/en/publications-data/guidelines-surveillance-native-mosquitoes-europe"}]$q$::jsonb, 'draft', null from public.vv_trap_types where key = $q$mosquito_magnet$q$
 and not exists (select 1 from public.vv_library_versions v join public.vv_trap_types t on t.id = v.trap_type_id where t.key = $q$mosquito_magnet$q$);
insert into public.vv_library_versions (kind, trap_type_id, version, content, sources, status, author_id)
 select $q$trap$q$, id, 1, $q${"summary":"Sampling larvae and pupae from standing water with a standard dipper. Finds breeding sites directly and supports control decisions.","how_it_works":"A dipper (typically about 350 ml) is lowered into the water at an angle; larvae and pupae are counted and collected for identification.","targets":["aedes_detritus","culex_pipiens_sl","anopheles_maculipennis_sl"],"life_stages":["larvae","pupae"],"setup":["Use a standard dipper and a white tray","Approach the water gently so larvae don't dive"],"placement":["Edges of standing water, among vegetation","Containers such as tyres and water butts (use a pipette for small containers)"],"servicing":"Record the number of dips per site so results are comparable.","tips":["Record water type (fresh, brackish), shade and vegetation"],"common_mistakes":["Too few dips to detect low numbers"],"images":[{"url":"https://thumb.wikimedia.org/wikipedia/commons/thumb/6/61/Mosquito_larvae_stagnant_water.jpg/960px-Mosquito_larvae_stagnant_water.jpg","credit":"Challiyan at Malayalam Wikipedia","licence":"CC BY 3.0","source_url":"https://commons.wikimedia.org/wiki/File:Mosquito_larvae_stagnant_water.jpg","caption":"Mosquito larvae in standing water"}]}$q$::jsonb, $q$[{"title":"ECDC: Guidelines for the surveillance of invasive mosquitoes in Europe","url":"https://www.ecdc.europa.eu/en/publications-data/guidelines-surveillance-invasive-mosquitoes-europe"},{"title":"ECDC: Guidelines for the surveillance of native mosquitoes in Europe","url":"https://www.ecdc.europa.eu/en/publications-data/guidelines-surveillance-native-mosquitoes-europe"}]$q$::jsonb, 'draft', null from public.vv_trap_types where key = $q$larval_dip$q$
 and not exists (select 1 from public.vv_library_versions v join public.vv_trap_types t on t.id = v.trap_type_id where t.key = $q$larval_dip$q$);
